#pragma once

#include <stddef.h>
#include <stdint.h>

#include "src/actuator/calibration_end_detector.h"

// Robot end-current replays for test_calibration_end_detector.cpp. Data only,
// generated (fw2 fix round, 2026-11-25) from every hip and knee jog in the
// robot logs of 2026-11-23/24 (firmware/fixround-inputs/2026-11-24/traces: the
// FRONT board's telemetry, about 19.5 frames per second, integer current).
// One sample per telemetry frame from the first nonzero PWM to the host's stop:
// e = drive edges since the drive started, i = the frame's current field x 10
// (tenths of an IS count; the telemetry truncates to whole counts), r = 1 once
// the PWM reached the move PWM. stopped: the count had stopped before the host
// stopped the drive; the replay then holds it 3 s more (robotEndReplaySamples).
// extendSwitch: a hip extend (its end is a limit switch too). The expected
// verdict, its sample k and the drive edges there are the firmware detector's
// own, each checked against what the joint did (see the tests). Groups:
//   EndCurrent: the scripted end-current jogs at PWM 80/120/150 (endcur-*,
//               firmware hallcal-1123; 111808 = FL leg, 112315 = FR leg).
//   Morning:    the PWM 128/150 runs of 2026-11-24 morning (clearance-FL-115032,
//               -121754, -140513, clearance-FR-115750 with the FRHL curl that
//               stalled 878 edges short of its switch, fr-recover, hipend-FL,
//               rodscale-*).
//   Clearance:  the afternoon clearance runs (clearance-FL-143330 .. -175604
//               except -173941).
//   EndTest:    clearance-FL-173941, the FL end test (knee switch and stop,
//               hip curl and extend switch, the PWM 80 stall at 841).
//   QuickTest:  the PWM 80 quick tests (quicktest-*), hips to the body.

struct RobotEndSample
{
    int16_t e;
    uint16_t i;
    uint8_t r;
};

enum class RobotEndGroup : uint8_t
{
    EndCurrent,
    Morning,
    Clearance,
    EndTest,
    QuickTest,
};

struct RobotEndMove
{
    const char *name;   // log#move index
    RobotEndGroup group;
    const char *joint;
    int pwm;
    bool retract;       // -PWM: the rod retracts
    bool curl;
    bool extendSwitch;  // a hip extend
    bool stopped;       // the count stopped before the host stop: the replay holds it 3 s
    CalibrationEnd expected;
    int k;              // sample index of the expected decision (-1: none)
    int edges;          // drive edges at the decision
    const RobotEndSample *samples;
    size_t count;
};

